<?php
namespace App\Models;
use Illuminate\Database\Eloquent\Model; use Illuminate\Database\Eloquent\Relations\{BelongsTo,MorphMany,HasMany};
class ActualCost extends Model { use \App\Traits\HasCompany; public const STATUSES=['draft','pending_approval','approved','rejected','cancelled']; protected $attributes=['status'=>'draft']; protected $fillable=['company_id','project_id','financial_commitment_id','budget_item_id','budget_line_id','party_id','name','amount','currency','budget_amount','exchange_rate_to_budget','incurred_at','created_by','correction_of_actual_cost_id','correction_reason']; protected $casts=['amount'=>'decimal:4','budget_amount'=>'decimal:4','exchange_rate_to_budget'=>'decimal:8','incurred_at'=>'date','submitted_at'=>'datetime','approved_at'=>'datetime']; public function project():BelongsTo{return $this->belongsTo(Project::class);} public function commitment():BelongsTo{return $this->belongsTo(FinancialCommitment::class,'financial_commitment_id');} public function item():BelongsTo{return $this->belongsTo(BudgetItem::class,'budget_item_id');} public function line():BelongsTo{return $this->belongsTo(BudgetLine::class,'budget_line_id');} public function party():BelongsTo{return $this->belongsTo(Party::class);} public function correctionOf():BelongsTo{return $this->belongsTo(self::class,'correction_of_actual_cost_id');} public function corrections():HasMany{return $this->hasMany(self::class,'correction_of_actual_cost_id');} public function allocations():MorphMany{return $this->morphMany(PaymentAllocation::class,'allocatable');} }
